         Set tSC=##class(Ens.Director).CreateBusinessService(..ServiceName,.tService)
         Set tSC=tService.OnTask() ; this will process first file it finds.

         //This will loop thriugh the files and process them
         While (('tService.%WaitForNextCallInterval)&&('tService.%QuitTask)) 
         {
         	Set tSC=tService.OnTask()
			}
         Set tService="" ;This is so that the FTP disconnects
         quit tSC
